impl TimeEntry {
    pub fn get_description(&self) -> String {
        match self.description.as_ref() {
            "" => constants::NO_DESCRIPTION.to_string(),
            _ => self.description.to_string(),
        }
    }

    pub fn get_duration(&self) -> Duration {
        match self.stop {
            Some(_) => Duration::seconds(self.duration),
            None => Utc::now().signed_duration_since(self.start),
        }
    }

    pub fn get_duration_hmmss(&self) -> String {
        let duration = self.get_duration();
        format!(
            "{}:{:02}:{:02}",
            duration.num_hours(),
            duration.num_minutes() % 60,
            duration.num_seconds() % 60
        )
    }

    pub fn is_running(&self) -> bool {
        self.duration.is_negative()
    }

    pub fn as_running_time_entry(&self, start: DateTime<Utc>) -> TimeEntry {
        TimeEntry {
            start,
            stop: None,
            duration: -start.timestamp(),
            created_with: Some(constants::CLIENT_NAME.to_string()),
            ..self.clone()
        }
    }

    pub fn get_display_tags(&self) -> String {
        if self.tags.is_empty() {
            "".to_string()
        } else {
            format!("[{}]", self.tags.join(", "))
        }

    fn network_organization_to_organization(
        network_organization: NetworkOrganization,
    ) -> Organization {
        Organization {
            id: network_organization.id,
            name: network_organization.name,
            admin: network_organization.admin,
            workspace_id: network_organization.workspace_id,
            workspace_name: network_organization.workspace_name,
            pricing_plan_name: network_organization.pricing_plan_name,
            permissions: network_organization.permissions.unwrap_or_default(),
        }
    }

    fn map_tasks(
        network_tasks: Vec<NetworkTask>,
        projects: &HashMap<i64, Project>,
    ) -> HashMap<i64, Task> {
        network_tasks
            .into_iter()
            .filter_map(|task| {
                projects.get(&task.project_id).map(|project| {
                    (
                        task.id,
                        Task {
                            id: task.id,
                            name: task.name,
                            project: project.clone(),
                            workspace_id: task.workspace_id,
                            active: task.active.unwrap_or(true),
                        },
                    )
                })
            })
            .collect()
    }

    fn map_network_time_entry(
        network_entry: NetworkTimeEntry,
        projects: &HashMap<i64, Project>,
        tasks: &HashMap<i64, Task>,
    ) -> TimeEntry {
        TimeEntry {
            id: network_entry.id,
            description: network_entry.description,
            start: network_entry.start,
            stop: network_entry.stop,
