        }
    }

    /// Hydrates a single NetworkTimeEntry by fetching projects/tasks/clients
    /// only when the entry references a project_id or task_id.
    async fn hydrate_single_network_entry(&self, network_entry: NetworkTimeEntry) -> TimeEntry {
        let has_project = network_entry.project_id.is_some();
        let has_task = network_entry.task_id.is_some();

        if !has_project && !has_task {
            return TimeEntry {
                id: network_entry.id,
                description: network_entry.description,
                start: network_entry.start,
                stop: network_entry.stop,
                duration: network_entry.duration,
                billable: network_entry.billable,
                workspace_id: network_entry.workspace_id,
                tags: network_entry.tags.unwrap_or_default(),
                project: None,
                task: None,
                ..Default::default()
            };
        }

        let (network_projects, network_tasks, network_clients) = tokio::join!(
            self.get_projects(),
            async {
                if has_task {
                    self.get_tasks().await
                } else {
                    Ok(Vec::new())
                }
            },
            .iter()
            .map(ToString::to_string)
            .collect::<Vec<_>>()
            .join(",");
        let url = format!(
            "{}/workspaces/{}/time_entries/{}",
            self.base_url, workspace_id, ids
        );
        self.patch::<Value, Value>(url, &patch).await
    }

    async fn get_time_entries_filtered(
        &self,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<Vec<TimeEntry>> {
        let (network_entries, network_projects, network_tasks, network_clients) = tokio::join!(
            self.get_time_entries(since.as_deref(), until.as_deref()),
            self.get_projects(),
            self.get_tasks(),
            self.get_clients(),
        );

        let clients: HashMap<i64, crate::models::Client> = network_clients
            .unwrap_or_default()
            .into_iter()
            .map(|c| {
                (
                    c.id,
                    crate::models::Client {
                        id: c.id,
                        name: c.name,
                        workspace_id: c.wid,
                        archived: c.archived,
                    },
                )
            })
            .collect();

        let projects: HashMap<i64, Project> = network_projects
            .unwrap_or_default()
            .into_iter()
            .map(|p| {
                (
                    p.id,
                    Project {
                        id: p.id,
                        name: p.name.clone(),
                        workspace_id: p.workspace_id,
                        client: clients.get(&p.client_id.unwrap_or(-1)).cloned(),
                        is_private: p.is_private,
                        active: p.active,
                        at: p.at,
                        created_at: p.created_at,
                        color: p.color,
                        billable: p.billable,
                    },
                )
            })
            .collect();

        let tasks: HashMap<i64, Task> = network_tasks
            .unwrap_or_default()
            .into_iter()
            .filter_map(|t| {
                projects.get(&t.project_id).map(|project| {
                    (
                        t.id,
                        Task {
                            id: t.id,
                            name: t.name,
                            project: project.clone(),
                            workspace_id: t.workspace_id,
                            active: t.active.unwrap_or(true),
                        },
                    )
                })
            })
            .collect();

        let entries = network_entries?
            .into_iter()
            .map(|te| TimeEntry {
                id: te.id,
                description: te.description,
                start: te.start,
                stop: te.stop,
                duration: te.duration,
                billable: te.billable,
                workspace_id: te.workspace_id,
                tags: te.tags.unwrap_or_default(),
                project: projects.get(&te.project_id.unwrap_or(-1)).cloned(),
                task: tasks.get(&te.task_id.unwrap_or(-1)).cloned(),
                ..Default::default()
            })
            .collect();

        Ok(entries)
    }

