use crate::api::client::ApiClient;
use crate::constants::NO_PROJECT;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use std::collections::HashMap;

const BILLING_UNIT_SECONDS: i64 = 15 * 60;

pub struct BillCommand;

impl BillCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = if since.is_some() || until.is_some() {
            utilities::normalize_time_entry_list_filters(since, until)?
        } else {
            (None, None)
        };

        let entries = api_client.get_time_entries_filtered(since, until).await?;
        let totals = aggregate_billable_time(&entries);

        if totals.is_empty() {
            println!("(no data)");
            return Ok(());
        }

        let total_seconds: i64 = totals.iter().map(|(_, seconds)| seconds).sum();
        for (project, seconds) in totals {
            println!("{seconds}s  {project}");
        }
        println!("{total_seconds}s  Total");
        Ok(())
    }
}

fn aggregate_billable_time(entries: &[TimeEntry]) -> Vec<(String, i64)> {
    let mut totals: HashMap<String, i64> = HashMap::new();

    for entry in entries
        .iter()
        .filter(|entry| entry.billable && !entry.is_running())
    {
        let rounded_seconds = round_up_to_billing_unit(entry.duration);
        let project = entry
            .project
            .as_ref()
            .map(|project| project.name.clone())
            .unwrap_or_else(|| NO_PROJECT.to_string());
        *totals.entry(project).or_default() += rounded_seconds;
    }

    let mut totals: Vec<_> = totals.into_iter().collect();
    totals.sort_by(|(left_name, left_seconds), (right_name, right_seconds)| {
        right_seconds
            .cmp(left_seconds)
            .then_with(|| left_name.cmp(right_name))
    });
    totals
}

fn round_up_to_billing_unit(seconds: i64) -> i64 {
    if seconds == 0 {
        0
    } else {
        ((seconds + BILLING_UNIT_SECONDS - 1) / BILLING_UNIT_SECONDS) * BILLING_UNIT_SECONDS
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::models::Project;
    use chrono::{DateTime, Utc};

    fn entry(id: i64, duration: i64, billable: bool, project: Option<&str>) -> TimeEntry {
        TimeEntry {
            id,
            description: String::new(),
            start: "2026-01-01T00:00:00Z".parse::<DateTime<Utc>>().unwrap(),
            stop: Some("2026-01-01T00:01:00Z".parse::<DateTime<Utc>>().unwrap()),
            duration,
            billable,
            workspace_id: 1,
            tags: Vec::new(),
            project: project.map(|name| Project {
                id: id + 100,
                name: name.to_string(),
                workspace_id: 1,
                client: None,
                is_private: false,
                active: true,
                at: DateTime::parse_from_rfc3339("2026-01-01T00:00:00Z")
                    .unwrap()
                    .with_timezone(&Utc),
                created_at: DateTime::parse_from_rfc3339("2026-01-01T00:00:00Z")
                    .unwrap()
                    .with_timezone(&Utc),
                color: String::new(),
                billable: None,
            }),
            task: None,
            created_with: None,
        }
    }

    #[test]
    fn filters_and_rounds_each_entry_before_grouping() {
        let mut running = entry(4, -1, true, Some("A"));
        running.stop = None;
        let entries = vec![
            entry(1, 7 * 60, true, Some("A")),
            entry(2, 22 * 60, true, Some("A")),
            entry(3, 15 * 60, true, Some("B")),
            entry(4, 60, false, Some("B")),
            running,
            entry(6, 14 * 60, true, None),
        ];

        assert_eq!(
            aggregate_billable_time(&entries),
            vec![
                ("A".to_string(), 45 * 60),
                ("B".to_string(), 15 * 60),
                ("No Project".to_string(), 15 * 60),
            ]
        );
    }

    #[test]
    fn ties_are_sorted_alphabetically() {
        let entries = vec![entry(1, 1, true, Some("Z")), entry(2, 1, true, Some("A"))];
        assert_eq!(
            aggregate_billable_time(&entries)[..2],
            [("A".to_string(), 900), ("Z".to_string(), 900)]
        );
    }
}
